import{_ as n,o as e,c as r,a2 as s,j as t,a}from"./chunks/framework.DxqK4cCD.js";const c=JSON.parse('{"title":"SpikeLogBERT: Energy-Efficient Log Parsing Using Spiking Transformer Networks","description":"SpikeLogBERT 首次将脉冲变压器网络与知识蒸馏结合，实现高精度、低能耗的日志解析，能效提升 62.6%。","frontmatter":{"title":"SpikeLogBERT: Energy-Efficient Log Parsing Using Spiking Transformer Networks","description":"SpikeLogBERT 首次将脉冲变压器网络与知识蒸馏结合，实现高精度、低能耗的日志解析，能效提升 62.6%。","date":"2026-07-01","arxivId":"2606.31781","domain":"计算机视觉 · 自然语言处理","level":"基础","tags":["脉冲神经网络","日志解析","知识蒸馏","变压器网络","能效优化"],"originalUrl":"https://arxiv.org/abs/2606.31781","sourceUrl":"https://github.com/vsvnakers/paper-daily/blob/master/essay_read/2026-07-01/2606.31781.md"},"headers":[],"relativePath":"papers/daily/2026-07-01/2606.31781.md","filePath":"papers/daily/2026-07-01/2606.31781.md","lastUpdated":1786541753000}'),l={name:"papers/daily/2026-07-01/2606.31781.md"};function o(p,i,h,g,d,E){return e(),r("div",null,[...i[0]||(i[0]=[s("",15),t("ul",null,[t("li",null,[t("strong",null,"脉冲神经元模型"),a("：使用 Leaky Integrate-and-Fire (LIF) 神经元作为基本计算单元。LIF 神经元通过膜电位积分、泄漏和脉冲发放机制实现事件驱动计算。其离散时间动力学方程为：$V[t] = \\beta V[t-1] + WX[t] - S[t-1]\\theta$，其中 $\\beta$ 是泄漏常数，$W$ 是突触权重，$X[t]$ 是输入，$S[t]$ 是脉冲输出，$\\theta$ 是阈值。")]),t("li",null,[t("strong",null,"脉冲自注意力机制"),a("：将标准 Transformer 中的自注意力计算替换为脉冲形式。首先，通过脉冲编码器将输入日志消息转换为脉冲序列。然后，在自注意力层中，查询（Query）、键（Key）和值（Value）矩阵的乘法被替换为脉冲驱动的加法操作，即 $\\text{Attention}(Q,K,V) = \\text{Softmax}(QK^T/\\sqrt{d})V$ 中的 $QK^T$ 被替换为 $\\sum_{t} S_Q[t] \\cdot S_K[t]$，其中 $S_Q$ 和 $S_K$ 是脉冲序列。")]),t("li",null,[t("strong",null,"知识蒸馏框架"),a("：使用预训练的 BERT 模型作为教师，SpikeLogBERT 作为学生。蒸馏损失函数包括：1）软标签蒸馏损失（Soft Label Distillation Loss），最小化教师和学生输出分布之间的 KL 散度（Kullback-Leibler Divergence）；2）中间层特征蒸馏损失（Intermediate Feature Distillation Loss），对齐教师和学生的隐藏状态表示。总损失为：$\\mathcal{L}"),t("em",{KD:""},"{total} = \\alpha \\mathcal{L}"),a(" + (1-\\alpha) \\mathcal{L}"),t("em",{KD:""},"{CE}$，其中 $\\mathcal{L}"),a("$ 是蒸馏损失，$\\mathcal{L}_{CE}$ 是交叉熵损失（Cross-Entropy Loss）。")]),t("li",null,[t("strong",null,"脉冲编码器"),a("：将原始日志消息的 token 嵌入（Token Embedding）转换为脉冲序列。采用速率编码（Rate Coding）或时间编码（Temporal Coding）将连续值嵌入映射为脉冲发放频率或时间。例如，速率编码中，嵌入值 $e_i$ 被映射为脉冲发放概率 $p_i = \\sigma(e_i)$，其中 $\\sigma$ 是 Sigmoid 函数。")]),t("li",null,[t("strong",null,"训练策略"),a("：采用两阶段训练。第一阶段，冻结教师模型，仅训练学生模型，使用蒸馏损失和交叉熵损失联合优化。第二阶段，微调整个学生模型，使用梯度替代法（Surrogate Gradient Method）解决脉冲神经元不可微的问题，常用替代函数为矩形函数或 Sigmoid 函数。")])],-1),s("",6),t("ol",null,[t("li",null,[t("p",null,[t("strong",null,"LIF 神经元动力学方程"),a("： $$V[t] = \\beta V[t-1] + WX[t] - S[t-1]\\theta$$ 其中 $V[t]$ 是时刻 $t$ 的膜电位，$\\beta$ 是泄漏常数，$W$ 是权重矩阵，$X[t]$ 是输入，$S[t-1]$ 是上一时刻的脉冲输出，$\\theta$ 是发放阈值。该方程描述了膜电位的积分、泄漏和重置过程。")])]),t("li",null,[t("p",null,[t("strong",null,"脉冲自注意力计算"),a("： $$\\text{Attention}(Q,K,V) = \\text{Softmax}\\left(\\frac{\\sum_{t=1}^T S_Q[t] \\cdot S_K[t]}{\\sqrt{d}}\\right) V$$ 其中 $S_Q[t]$ 和 $S_K[t]$ 分别是查询和键在时间步 $t$ 的脉冲序列，$d$ 是维度。该公式将标准自注意力的矩阵乘法替换为脉冲序列的点积求和，实现加法计算。")])]),t("li",null,[t("p",null,[t("strong",null,"知识蒸馏总损失"),a("： $$\\mathcal{L}"),t("em",{teacher:""},"{total} = \\alpha \\cdot \\text{KL}(p"),a(" || p_{student}) + (1-\\alpha) \\cdot \\mathcal{L}"),t("em",{student:""},"{CE}(y, p"),a(")$$ 其中 $p_{teacher}$ 和 $p_{student}$ 是教师和学生的输出概率分布，$\\mathcal{L}_{CE}$ 是交叉熵损失，$\\alpha$ 是平衡超参数。")])])],-1),s("",35)])])}const u=n(l,[["render",o]]);export{c as __pageData,u as default};
